137	
138	      } else if (iequals(log_type, "console")) {
139	        data.log_config =
140	            std::make_shared<GlobalConfig::ConsoleLogConfig>(log_level);
141	      } else {
142	        throw py::value_error("log_type must be 'console' or 'file'");
143	      }
144	    }
145	
146	    // set query thread count
147	    if (has_key(config_dict, "query_threads")) {
148	      auto q = get_if<int32_t>(config_dict, "query_threads").value();
149	      if (q <= 0) throw py::value_error("query_threads must be positive");
150	      data.query_thread_count = static_cast<uint32_t>(q);
151	    }
152	
153	    // set optimize thread count
154	    if (has_key(config_dict, "optimize_threads")) {
155	      auto o = get_if<int32_t>(config_dict, "optimize_threads").value();
156	      if (o <= 0) throw py::value_error("optimize_threads must be positive");
157	      data.optimize_thread_count = static_cast<uint32_t>(o);
158	    }
159	
160	    // set invert_to_forward_scan_ratio
161	    if (has_key(config_dict, "invert_to_forward_scan_ratio")) {
162	      auto v =
163	          get_if<double>(config_dict, "invert_to_forward_scan_ratio").value();
164	      if (v < 0.0 || v > 1.0) {
165	        throw py::value_error(
166	            "invert_to_forward_scan_ratio must be in [0.0, 1.0]");
167	      }
168	      data.invert_to_forward_scan_ratio = static_cast<float>(v);
169	    }
170	
171	    // set brute_force_by_keys_ratio
172	    if (has_key(config_dict, "brute_force_by_keys_ratio")) {
173	      auto v = get_if<double>(config_dict, "brute_force_by_keys_ratio").value();
174	      if (v < 0.0 || v > 1.0) {
