182	    if (has_key(config_dict, "fts_brute_force_by_keys_ratio")) {
183	      auto v =
184	          get_if<double>(config_dict, "fts_brute_force_by_keys_ratio").value();
185	      if (v < 0.0 || v > 1.0) {
186	        throw py::value_error(
187	            "fts_brute_force_by_keys_ratio must be in [0.0, 1.0]");
188	      }
189	      data.fts_brute_force_by_keys_ratio = static_cast<float>(v);
190	    }
191	
192	    // initialize (contains validate)
193	    Status status = GlobalConfig::Instance().initialize(data);
