952	Status CollectionImpl::optimize(const OptimizeOptions &options) {
953	  CHECK_COLLECTION_READONLY_RETURN_STATUS;
954	
955	  // Serialize against other maintenance operations for the whole optimize.
956	  std::lock_guard maintenance_lock(maintenance_mtx_);
957	
958	  std::vector<Segment::Ptr> persist_segments;
959	
960	  // Phase 1: exclusively seal the current writing segment and snapshot
961	  // the persisted segment set.
962	  {
963	    std::unique_lock schema_lock(schema_handle_mtx_);
964	    // Nothing has been built yet, so failing fast leaves nothing to clean.
965	    CHECK_RETURN_STATUS(check_no_active_iterators("optimize"));
966	    std::lock_guard write_lock(write_mtx_);
967	
968	    CHECK_DESTROY_RETURN_STATUS(destroyed_, false);
969	    CHECK_CLOSED_RETURN_STATUS(closed_, false);
970	
971	    if (writing_segment_->has_record()) {
972	      auto s = switch_to_new_segment_for_writing();
973	      if (!s.ok()) {
974	        return s;
975	      }
976	    }
977	
978	    persist_segments =
979	        get_all_persist_segments();  // will not return writing segment
980	  }
981	
982	  if (persist_segments.size() == 0) {
983	    return Status::OK();
984	  }
985	
986	  // Phase 2: lock-free optimize. Readers and writers proceed freely.
987	  auto delete_store_clone = delete_store_->clone();
988	  auto tasks =
989	      build_compact_task(schema_, persist_segments, options.concurrency_,
990	                         delete_store_clone->make_filter());
991	  auto s = execute_compact_task(tasks);
992	  CHECK_RETURN_STATUS(s);
993	
994	  // End of phase 2 (still lock-free): move built tmp segments to their
995	  // final paths and open them before the manifest is persisted, so a
996	  // failure aborts cleanly without a version/disk mismatch.
997	  std::vector<Segment::Ptr> opened_segments;
998	  std::vector<std::string> moved_dirs;
999	  auto cleanup_moved_dirs = [&]() {
1000	    for (auto &dir : moved_dirs) {
1001	      FileHelper::RemoveDirectory(dir);
1002	    }
1003	  };
1004	  for (auto &task : tasks) {
1005	    auto task_info = task->task_info();
1006	    if (!std::holds_alternative<CompactTask>(task_info)) {
1007	      continue;
1008	    }
1009	    auto compact_task = std::get<CompactTask>(task_info);
1010	    if (!compact_task.output_segment_meta_) {
1011	      continue;
1012	    }
1013	
1014	    auto tmp_segment_path =
1015	        FileHelper::MakeTempSegmentPath(path_, compact_task.output_segment_id_);
1016	    auto new_segment_id = allocate_segment_id();
1017	    auto new_segment_path = FileHelper::MakeSegmentPath(path_, new_segment_id);
1018	
1019	    if (!FileHelper::MoveDirectory(tmp_segment_path, new_segment_path)) {
1020	      cleanup_moved_dirs();
1021	      return Status::InternalError("move segment directory failed");
1022	    }
1023	    moved_dirs.push_back(new_segment_path);
1024	    compact_task.output_segment_meta_->set_id(new_segment_id);
1025	
1026	    auto new_segment =
1027	        Segment::Open(path_, *schema_, *compact_task.output_segment_meta_,
1028	                      id_map_, delete_store_, version_manager_,
1029	                      SegmentOptions{true, options_.enable_mmap_});
1030	    if (!new_segment.has_value()) {
1031	      // best-effort cleanup: these directories are not referenced by any
1032	      // manifest yet, so remove them rather than leaking them on disk
1033	      cleanup_moved_dirs();
1034	      return new_segment.error();
1035	    }
1036	    opened_segments.push_back(new_segment.value());
1037	  }
1038	
1039	  // Phase 3: short exclusive commit. No readers can be using the old
1040	  // indexers — they all hold the shared schema lock — so in-place
1041	  // reload_vector_index() is safe.
1042	  {
1043	    // No iterator wait: phase 1 rejects open iterators and create_iterator
1044	    // is rejected while optimize holds maintenance_mtx_, so the count is
1045	    // zero here.
1046	    std::unique_lock schema_lock(schema_handle_mtx_);
1047	    std::lock_guard write_lock(write_mtx_);
1048	
1049	    Version new_version = version_manager_->get_current_version();
1050	
1051	    for (auto &task : tasks) {
1052	      auto task_info = task->task_info();
1053	
1054	      if (std::holds_alternative<CompactTask>(task_info)) {
1055	        auto compact_task = std::get<CompactTask>(task_info);
1056	
1057	        if (compact_task.output_segment_meta_) {
1058	          s = new_version.add_persisted_segment_meta(
1059	              compact_task.output_segment_meta_);
1060	          CHECK_RETURN_STATUS(s);
1061	          new_version.set_next_segment_id(segment_id_allocator_.load());
1062	        }
1063	
1064	        for (auto input_segment : compact_task.input_segments_) {
1065	          s = new_version.remove_persisted_segment_meta(input_segment->id());
1066	          CHECK_RETURN_STATUS(s);
1067	        }
1068	      } else if (std::holds_alternative<CreateVectorIndexTask>(task_info)) {
1069	        auto create_index_task = std::get<CreateVectorIndexTask>(task_info);
1070	        s = new_version.update_persisted_segment_meta(
1071	            create_index_task.output_segment_meta_);
1072	        CHECK_RETURN_STATUS(s);
1073	      }
1074	    }
1075	
1076	    s = version_manager_->apply(new_version);
1077	    CHECK_RETURN_STATUS(s);
1078	
1079	    s = version_manager_->flush();
1080	    CHECK_RETURN_STATUS(s);
1081	
1082	    // publish new segments, retire compacted inputs and reload rebuilt
1083	    // vector indexes
1084	    size_t opened_index = 0;
1085	    for (auto &task : tasks) {
1086	      auto task_info = task->task_info();
1087	
1088	      if (std::holds_alternative<CompactTask>(task_info)) {
1089	        auto compact_task = std::get<CompactTask>(task_info);
1090	
1091	        if (compact_task.output_segment_meta_) {
1092	          if (opened_index >= opened_segments.size()) {
1093	            return Status::InternalError("opened_segments index out of bounds");
1094	          }
1095	          s = segment_manager_->add_segment(opened_segments[opened_index++]);
1096	          CHECK_RETURN_STATUS(s);
1097	        }
1098	
1099	        for (auto input_segment : compact_task.input_segments_) {
1100	          s = segment_manager_->destroy_segment(input_segment->id());
1101	          CHECK_RETURN_STATUS(s);
1102	        }
1103	      } else if (std::holds_alternative<CreateVectorIndexTask>(task_info)) {
1104	        auto create_index_task = std::get<CreateVectorIndexTask>(task_info);
1105	
1106	        s = create_index_task.input_segment_->reload_vector_index(
1107	            *schema_, create_index_task.output_segment_meta_,
1108	            create_index_task.output_vector_indexers_,
1109	            create_index_task.output_quant_vector_indexers_);
1110	        CHECK_RETURN_STATUS(s);
1111	      }
1112	    }
1113	  }
1114	
1115	  // segment_manager_->destroy_segment() / Segment::destroy() closes the retired
1116	  // segments while the task still hold the shared_ptr of them. Clear to drop
1117	  // the compaction snapshots after releasing the write_mtx so the segment
1118	  // destructors perform recursive directory cleanup without blocking readers
1119	  // and writers.
1120	  tasks.clear();
1121	  persist_segments.clear();
1122	
1123	  return Status::OK();
1124	}
