1215	Status CollectionImpl::execute_compact_task(
1216	    std::vector<SegmentTask::Ptr> &tasks) const {
1217	  Status s;
1218	  for (auto &task : tasks) {
1219	    s = SegmentHelper::Execute(task);
1220	    if (!s.ok()) {
1221	      return s;
1222	    }
1223	  }
1224	
1225	  return Status::OK();
1226	}
