1126	std::vector<SegmentTask::Ptr> CollectionImpl::build_compact_task(
1127	    const CollectionSchema::Ptr &schema,
1128	    const std::vector<Segment::Ptr> &segments, int concurrency,
1129	    const IndexFilter::Ptr filter) {
1130	  std::vector<SegmentTask::Ptr> tasks;
1131	  if (segments.empty()) return tasks;
1132	
1133	  size_t current_physical_doc_count = 0;
1134	  size_t current_live_doc_count = 0;
1135	  for (auto &segment : segments) {
1136	    current_physical_doc_count += segment->doc_count();
1137	    current_live_doc_count += segment->doc_count(filter);
1138	  }
1139	  const bool purge_deleted_docs =
1140	      current_live_doc_count <
1141	      current_physical_doc_count * (1 - COMPACT_DELETE_RATIO_THRESHOLD);
1142	
1143	  auto max_doc_count_per_segment = schema->max_doc_count_per_segment();
1144	
1145	  std::vector<Segment::Ptr> current_group;
1146	  current_physical_doc_count = 0;
1147	  current_live_doc_count = 0;
1148	
1149	  for (const auto &seg : segments) {
1150	    const auto seg_physical_doc_count = seg->doc_count();
1151	    const auto seg_live_doc_count = seg->doc_count(filter);
1152	
1153	    if (!current_group.empty()) {
1154	      SegmentTask::Ptr task;
1155	      bool skip_task{false};
1156	      if (purge_deleted_docs) {
1157	        if (current_live_doc_count + seg_live_doc_count >
1158	            max_doc_count_per_segment) {
1159	          // Compaction physically removes deleted rows.
1160	          task = SegmentTask::CreateCompactTask(
1161	              CompactTask{path_, schema, current_group,
1162	                          allocate_segment_id_for_tmp_segment(), filter,
1163	                          !options_.enable_mmap_, concurrency});
1164	        }
1165	      } else {
1166	        if (current_physical_doc_count + seg_physical_doc_count >
1167	            max_doc_count_per_segment) {
1168	          if (current_group.size() == 1) {
1169	            task =
1170	                SegmentTask::CreateCreateVectorIndexTask(CreateVectorIndexTask{
1171	                    current_group[0], "", nullptr, concurrency});
1172	            skip_task = current_group[0]->all_vector_index_ready();
1173	          } else {
1174	            // Merge segments while preserving deleted rows.
1175	            task = SegmentTask::CreateCompactTask(
1176	                CompactTask{path_, schema, current_group,
1177	                            allocate_segment_id_for_tmp_segment(), nullptr,
1178	                            !options_.enable_mmap_, concurrency});
1179	          }
1180	        }
1181	      }
1182	
1183	      if (task) {
1184	        current_group.clear();
1185	        current_physical_doc_count = 0;
1186	        current_live_doc_count = 0;
1187	        if (!skip_task) {
1188	          tasks.push_back(task);
1189	        }
1190	      }
1191	    }
1192	
1193	    current_group.push_back(seg);
1194	    current_physical_doc_count += seg_physical_doc_count;
1195	    current_live_doc_count += seg_live_doc_count;
1196	  }
1197	
1198	  if (current_group.size() > 0) {
1199	    SegmentTask::Ptr task;
1200	    if (current_group.size() == 1 && !purge_deleted_docs) {
1201	      task = SegmentTask::CreateCreateVectorIndexTask(
1202	          CreateVectorIndexTask{current_group[0], "", nullptr, concurrency});
1203	    } else {
1204	      task = SegmentTask::CreateCompactTask(CompactTask{
1205	          path_, schema, current_group, allocate_segment_id_for_tmp_segment(),
1206	          purge_deleted_docs ? filter : nullptr, !options_.enable_mmap_,
1207	          concurrency});
1208	    }
1209	    tasks.push_back(task);
1210	  }
1211	
1212	  return tasks;
1213	}
