635	Status SegmentHelper::ReduceVectorIndex(
636	    const CollectionSchema::Ptr schema,
637	    const std::vector<Segment::Ptr> &input_segments,
638	    const std::string &output_segment_path, const IndexFilter::Ptr &filter,
639	    std::function<BlockID()> &block_id_generator, uint64_t min_doc_id,
640	    uint64_t max_doc_id, uint32_t doc_count, int concurrency,
641	    std::vector<BlockMeta> *output_block_metas) {
642	  Status s;
643	
644	  // vector
645	  auto vector_fields = schema->vector_fields();
646	  for (auto &field : vector_fields) {
647	    auto vector_index_params =
648	        std::dynamic_pointer_cast<VectorIndexParams>(field->index_params());
649	
650	    using FetchIndexersFn =
651	        std::vector<VectorColumnIndexer::Ptr> (Segment::*)(const std::string &)
652	            const;
653	    auto collect_merge_indexers = [&](FetchIndexersFn fetch) {
654	      std::vector<VectorColumnIndexer::Ptr> source_indexers;
655	      for (const auto &seg : input_segments) {
656	        auto seg_indexers = (seg.get()->*fetch)(field->name());
657	        source_indexers.insert(source_indexers.end(), seg_indexers.begin(),
658	                               seg_indexers.end());
659	      }
660	      return source_indexers;
661	    };
662	
663	    auto vector_block_id = block_id_generator();
664	    if (vector_index_params->quantize_type() == QuantizeType::UNDEFINED) {
665	      auto vector_index_path = FileHelper::MakeVectorIndexPath(
666	          output_segment_path, field->name(), vector_block_id);
667	
668	      s = MergeWithOptionalReuse(
669	          vector_index_path, *field,
670	          collect_merge_indexers(&Segment::get_vector_indexer), filter,
671	          concurrency, nullptr);
672	      CHECK_RETURN_STATUS(s);
673	
674	      BlockMeta new_block_meta;
675	      new_block_meta.set_id(vector_block_id);
676	      new_block_meta.set_type(BlockType::VECTOR_INDEX);
677	      new_block_meta.set_columns({field->name()});
678	      new_block_meta.set_min_doc_id(min_doc_id);
679	      new_block_meta.set_max_doc_id(max_doc_id);
680	      new_block_meta.set_doc_count(doc_count);
681	
682	      output_block_metas->push_back(new_block_meta);
683	    } else {
684	      auto vector_index_path = FileHelper::MakeVectorIndexPath(
685	          output_segment_path, field->name(), vector_block_id);
686	
687	      auto field_without_quantize = std::make_shared<FieldSchema>(*field);
688	      field_without_quantize->set_index_params(MakeDefaultVectorIndexParams(
689	          vector_index_params->metric_type(),
690	          vector_index_params->use_flat_contiguous_memory(),
691	          segment_detail::FlatStorageDataTypeForField(
692	              field->data_type(), vector_index_params->flat_data_type())));
693	
694	      VectorColumnIndexer::Ptr vector_indexer;
695	      s = MergeWithOptionalReuse(
696	          vector_index_path, *field_without_quantize,
697	          collect_merge_indexers(&Segment::get_vector_indexer), filter,
698	          concurrency,
699	          vector_index_params->type() == IndexType::IVF ? nullptr
700	                                                        : &vector_indexer);
701	      CHECK_RETURN_STATUS(s);
702	
703	      // IVF trains from the input segments' quantized indexers, not this new
704	      // raw Flat. Flush and close it inside MergeWithOptionalReuse so its
705	      // storage does not overlap the IVF training and dump working sets.
706	      // HNSW_RABITQ training relies on the raw provider held by the flat
707	      // indexer, so its Close() is deferred until after the quantize indexer
708	      // is written.
709	      core::IndexProvider::Pointer raw_vector_provider;
710	      if (vector_index_params->type() == IndexType::HNSW_RABITQ) {
711	        raw_vector_provider = vector_indexer->create_index_provider();
712	      }
713	
714	      std::shared_ptr<FieldSchema> field_for_quantize;
715	      s = PrepareQuantizeField(*field, raw_vector_provider,
716	                               &field_for_quantize);
717	      CHECK_RETURN_STATUS(s);
718	
719	      BlockMeta new_block_meta;
720	      new_block_meta.set_id(vector_block_id);
721	      new_block_meta.set_type(BlockType::VECTOR_INDEX);
722	      new_block_meta.set_columns({field->name()});
723	      new_block_meta.set_min_doc_id(min_doc_id);
724	      new_block_meta.set_max_doc_id(max_doc_id);
725	      new_block_meta.set_doc_count(doc_count);
726	      output_block_metas->push_back(new_block_meta);
727	
728	      // create quantize index
729	      auto vector_quan_block_id = block_id_generator();
730	
731	      auto vector_quan_index_path = FileHelper::MakeQuantizeVectorIndexPath(
732	          output_segment_path, field->name(), vector_quan_block_id);
733	
734	      // Per-record quantizers can concatenate the payloads produced during
735	      // insert. Quantizers requiring full-dataset training must consume the
736	      // raw Flat sources and train again for the merged segment.
737	      auto quant_merge_sources =
738	          segment_detail::CanReuseInsertTimeQuantizedVectors(
739	              vector_index_params->quantize_type())
740	              ? collect_merge_indexers(&Segment::get_quant_vector_indexer)
741	              : collect_merge_indexers(&Segment::get_vector_indexer);
742	
743	      s = MergeWithOptionalReuse(vector_quan_index_path, *field_for_quantize,
744	                                 quant_merge_sources, filter, concurrency,
745	                                 nullptr);
746	      CHECK_RETURN_STATUS(s);
747	
748	      if (vector_indexer != nullptr) {
749	        s = vector_indexer->close();
750	        CHECK_RETURN_STATUS(s);
751	      }
752	
753	      new_block_meta.set_id(vector_quan_block_id);
754	      new_block_meta.set_type(BlockType::VECTOR_INDEX_QUANTIZE);
755	      new_block_meta.set_columns({field->name()});
756	      new_block_meta.set_min_doc_id(min_doc_id);
757	      new_block_meta.set_max_doc_id(max_doc_id);
758	      new_block_meta.set_doc_count(doc_count);
759	      output_block_metas->push_back(new_block_meta);
760	    }
761	  }
762	
763	  return Status::OK();
764	}
