768	// Only the first indexer's file is reused as the merge base; the remaining
769	// indexers are merged in via Merge(). Reuse is restricted to streaming
770	// indexes (HNSW, FLAT). Builder-rebuild indexes (IVF, VAMANA) and HNSW_RABITQ,
771	// IVF_RABITQ fall back to the full-rebuild merge.
772	bool CanReuseFirstIndexer(const std::vector<VectorColumnIndexer::Ptr> &indexers,
773	                          const FieldSchema &output_field,
774	                          const IndexFilter::Ptr &filter) {
775	  if (filter != nullptr || indexers.empty()) {
776	    return false;
777	  }
778	  if (output_field.index_type() != IndexType::HNSW &&
779	      output_field.index_type() != IndexType::FLAT) {
780	    return false;
781	  }
782	  const auto &first_field = indexers.front()->field_schema();
783	  if (first_field.index_type() != output_field.index_type()) {
784	    return false;
785	  }
786	
787	  // When creating a quantized column, the fp32 indexers will be merged into a
788	  // quantized vector indexer.
789	  auto quantize_type_of = [](const FieldSchema &f) {
790	    auto params =
791	        std::dynamic_pointer_cast<VectorIndexParams>(f.index_params());
792	    return params ? params->quantize_type() : QuantizeType::UNDEFINED;
793	  };
794	  return quantize_type_of(first_field) == quantize_type_of(output_field);
795	}
796	
797	}  // namespace
