1417	                 const IndexFilter &filter, const MergeOptions &options) {
1418	  if (indexes.empty()) {
1419	    return core::IndexError_Success;
1420	  }
1421	  // ivf need builder
1422	  auto reducer =
1423	      core::IndexFactory::CreateStreamerReducer("MixedStreamerReducer");
1424	  if (reducer == nullptr) {
1425	    LOG_ERROR("Failed to create reducer");
1426	    return core::IndexError_Runtime;
1427	  }
1428	
1429	  if (options.write_concurrency == 0) {
1430	    LOG_ERROR("Write concurrency must be greater than 0");
1431	    return core::IndexError_InvalidArgument;
1432	  }
1433	  // must declare here to ensure its lifespan can cover reducer->reduce()
1434	  std::unique_ptr<ailego::ThreadPool> local_thread_pool = nullptr;
1435	  uint32_t effective_write_concurrency = options.write_concurrency;
1436	  if (options.pool != nullptr) {
1437	    reducer->set_thread_pool(options.pool);
1438	    effective_write_concurrency =
1439	        std::min<uint32_t>(effective_write_concurrency, options.pool->count());
1440	  } else {
1441	    local_thread_pool =
1442	        std::make_unique<ailego::ThreadPool>(options.write_concurrency, false);
1443	    reducer->set_thread_pool(local_thread_pool.get());
1444	    effective_write_concurrency =
1445	        static_cast<uint32_t>(local_thread_pool->count());
1446	  }
1447	
1448	  ailego::Params reducer_params;
1449	  reducer_params.set(core::PARAM_MIXED_STREAMER_REDUCER_ENABLE_PK_REWRITE,
1450	                     true);
1451	  reducer_params.set(core::PARAM_MIXED_STREAMER_REDUCER_NUM_OF_ADD_THREADS,
1452	                     effective_write_concurrency);
1453	  if (reducer->init(reducer_params) != 0) {
1454	    LOG_ERROR("Failed to init reducer");
1455	    return core::IndexError_Runtime;
1456	  }
1457	  if (converter_ != nullptr && reformer_ == nullptr) {
1458	    std::vector<MergeSourceIndexHolder::Source> sources;
1459	    sources.reserve(indexes.size());
1460	    for (const auto &index : indexes) {
1461	      auto provider = index->create_index_provider();
1462	      if (!provider || index->is_sparse_ ||
1463	          index->input_vector_meta_.data_type() !=
1464	              input_vector_meta_.data_type() ||
1465	          index->input_vector_meta_.dimension() !=
1466	              input_vector_meta_.dimension() ||
1467	          (!index->reformer_ && !index->turbo_quantizer_ &&
1468	           (provider->data_type() != input_vector_meta_.data_type() ||
1469	            provider->dimension() != input_vector_meta_.dimension() ||
1470	            provider->element_size() != input_vector_meta_.element_size()))) {
1471	        LOG_ERROR("Merge-source vector type mismatch");
1472	        return core::IndexError_Mismatch;
1473	      }
1474	      // Preserve the stored layout, including packed dimensions and norm tails.
1475	      const auto &meta = index->streamer_->meta();
1476	      core::IndexQueryMeta stored_meta{
1477	          meta.meta_type(),
1478	          provider->data_type(),
1479	          meta.unit_size(),
1480	          static_cast<uint32_t>(provider->dimension()),
1481	          index->turbo_quantizer_
1482	              ? static_cast<uint32_t>(index->turbo_quantizer_->type())
1483	              : 0,
1484	          meta.extra_meta_size()};
1485	      sources.push_back({std::move(provider), index->reformer_,
1486	                         index->turbo_quantizer_, std::move(stored_meta)});
1487	    }
1488	    auto holder = std::make_shared<MergeSourceIndexHolder>(std::move(sources),
1489	                                                           input_vector_meta_);
1490	    if (holder->error() != 0) return holder->error();
1491	    if (holder->count() == 0) {
1492	      LOG_ERROR("No vectors available to train converter");
1493	      return core::IndexError_InvalidArgument;
1494	    }
1495	    int ret = converter_->train(holder);
1496	    if (holder->error() != 0) return holder->error();
1497	    if (ret != 0) {
1498	      LOG_ERROR("Failed to train converter from merge sources");
1499	      return ret;
1500	    }
