1528	int Index::_get_coarse_search_topk(
1529	    const BaseIndexQueryParam::Pointer &search_param) {
1530	  float scale_factor = search_param->refiner_param->scale_factor_;
1531	  if (!std::isfinite(scale_factor) || scale_factor < 0) {
1532	    LOG_ERROR("Invalid refine scale factor or candidate count");
1533	    return core::IndexError_InvalidArgument;
1534	  }
1535	  if (scale_factor == 0) {
1536	    scale_factor = 1;
1537	  } else if (scale_factor < 1.0f) {
1538	    LOG_WARN("Refine scale factor %f is less than 1, using 1 instead",
1539	             scale_factor);
1540	    scale_factor = 1;
1541	  }
1542	  const float count = std::floor(search_param->topk * scale_factor);
1543	  if (!std::isfinite(count) ||
1544	      static_cast<double>(count) > (std::numeric_limits<int>::max)()) {
1545	    LOG_ERROR("Invalid refine scale factor or candidate count");
1546	    return core::IndexError_InvalidArgument;
1547	  }
1548	  return static_cast<int>(count);
1549	}
