1551	// Set or clear group-by state on a pooled context before each search.
1552	//
1553	// Set group-by state before topk so contexts can derive the effective candidate
1554	// count from the active group parameters. This order also ensures pooled
1555	// contexts restore the ordinary topk after stale group-by state is cleared.
1556	void Index::_set_group_by_on_context(
1557	    const BaseIndexQueryParam::Pointer &search_param,
1558	    core::IndexContext::Pointer &context) {
1559	  if (search_param->group_by_param && search_param->group_by_param->group_by) {
1560	    context->set_group_by(search_param->group_by_param->group_by);
1561	    context->set_group_params(search_param->group_by_param->group_count,
1562	                              search_param->group_by_param->group_topk);
1563	  } else {
1564	    context->set_group_params(0, 0);
1565	    context->reset_group_by();
1566	  }
1567	}
